// Package codec provides shared little-endian binary encoding and decoding
// primitives used by the Go client library.
package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
	"runtime"
)

// Reader is a binary deserializer that reads sequentially from a byte slice
// using little-endian encoding. It accumulates errors silently: once an error
// is set, all subsequent reads return zero values without overwriting it.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader that reads from payload.
func NewReader(payload []byte) *Reader {
	return &Reader{buf: payload}
}

// callerLoc returns the "file:line" of the caller, skipping skip frames above
// callerLoc itself.
func callerLoc(skip int) string {
	_, file, line, ok := runtime.Caller(skip + 1)
	if !ok {
		return "?:0"
	}
	return fmt.Sprintf("%s:%d", file, line)
}

// need reports whether n bytes remain to be read. If not (or if an error has
// already been recorded) it records an overrun error and returns false.
func (r *Reader) need(n int) bool {
	if r.err != nil {
		return false
	}
	if avail := len(r.buf) - r.pos; avail < n {
		r.err = fmt.Errorf("reader: need %d bytes at %s, have %d", n, callerLoc(2), avail)
		return false
	}
	return true
}

// U8 reads 1 byte as a uint8.
func (r *Reader) U8() uint8 {
	if !r.need(1) {
		return 0
	}
	v := r.buf[r.pos]
	r.pos++
	return v
}

// U16 reads 2 bytes as a little-endian uint16.
func (r *Reader) U16() uint16 {
	if !r.need(2) {
		return 0
	}
	v := binary.LittleEndian.Uint16(r.buf[r.pos:])
	r.pos += 2
	return v
}

// U32 reads 4 bytes as a little-endian uint32.
func (r *Reader) U32() uint32 {
	if !r.need(4) {
		return 0
	}
	v := binary.LittleEndian.Uint32(r.buf[r.pos:])
	r.pos += 4
	return v
}

// U64 reads 8 bytes as a little-endian uint64.
func (r *Reader) U64() uint64 {
	if !r.need(8) {
		return 0
	}
	v := binary.LittleEndian.Uint64(r.buf[r.pos:])
	r.pos += 8
	return v
}

// F32 reads 4 bytes as an IEEE 754 little-endian float32.
func (r *Reader) F32() float32 {
	if !r.need(4) {
		return 0
	}
	v := math.Float32frombits(binary.LittleEndian.Uint32(r.buf[r.pos:]))
	r.pos += 4
	return v
}

// Str reads exactly n bytes and returns them as a string.
func (r *Reader) Str(n int) string {
	if !r.need(n) {
		return ""
	}
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// U32LenStr reads a 4-byte little-endian uint32 length prefix followed by that
// many bytes as a string.
func (r *Reader) U32LenStr() string {
	if !r.need(4) {
		return ""
	}
	n := int(binary.LittleEndian.Uint32(r.buf[r.pos:]))
	r.pos += 4
	if !r.need(n) {
		return ""
	}
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// U8LenStr reads a 1-byte uint8 length prefix followed by that many bytes as a
// string.
func (r *Reader) U8LenStr() string {
	if !r.need(1) {
		return ""
	}
	n := int(r.buf[r.pos])
	r.pos++
	if !r.need(n) {
		return ""
	}
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// Raw reads exactly n bytes and returns them as a []byte copy.
func (r *Reader) Raw(n int) []byte {
	if !r.need(n) {
		return nil
	}
	b := make([]byte, n)
	copy(b, r.buf[r.pos:r.pos+n])
	r.pos += n
	return b
}

// Obj reads n bytes and passes them to v.UnmarshalBinary. If UnmarshalBinary
// returns an error, it is recorded in the Reader.
func (r *Reader) Obj(n int, v encoding.BinaryUnmarshaler) {
	if !r.need(n) {
		return
	}
	if err := v.UnmarshalBinary(r.buf[r.pos : r.pos+n]); err != nil && r.err == nil {
		r.err = err
	}
	r.pos += n
}

// Remaining returns the number of unconsumed bytes in the buffer.
func (r *Reader) Remaining() int {
	return len(r.buf) - r.pos
}

// Err returns the accumulated error, or nil if none occurred.
func (r *Reader) Err() error {
	return r.err
}
