package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
)

// Writer is a binary serializer that appends sequentially to an internal byte
// slice using little-endian encoding. It accumulates errors silently: once an
// error is set, all subsequent writes are no-ops and Bytes returns an empty
// slice.
type Writer struct {
	p   []byte
	err error
}

// NewWriter returns an empty Writer.
func NewWriter() *Writer {
	return &Writer{}
}

// NewWriterCap returns a Writer with a buffer pre-allocated to hold at least n
// bytes without reallocation.
func NewWriterCap(n int) *Writer {
	return &Writer{p: make([]byte, 0, n)}
}

// U8 appends v as 1 byte.
func (w *Writer) U8(v uint8) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, v)
}

// U16 appends v as 2 little-endian bytes.
func (w *Writer) U16(v uint16) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint16(w.p, v)
}

// U32 appends v as 4 little-endian bytes.
func (w *Writer) U32(v uint32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, v)
}

// U64 appends v as 8 little-endian bytes.
func (w *Writer) U64(v uint64) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint64(w.p, v)
}

// F32 appends v as 4 IEEE 754 little-endian bytes.
func (w *Writer) F32(v float32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, math.Float32bits(v))
}

// Str appends the raw bytes of s with no length prefix.
func (w *Writer) Str(s string) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, s...)
}

// U32LenStr appends a 4-byte little-endian uint32 length prefix followed by the
// bytes of s.
func (w *Writer) U32LenStr(s string) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, uint32(len(s)))
	w.p = append(w.p, s...)
}

// U8LenStr appends a 1-byte uint8 length prefix followed by the bytes of s. If
// s exceeds 255 bytes, an error is recorded and the buffer is left unchanged.
func (w *Writer) U8LenStr(s string) {
	if w.err != nil {
		return
	}
	if len(s) > 255 {
		w.err = fmt.Errorf("string length %d exceeds 255 at %s", len(s), callerLoc(1))
		return
	}
	w.p = append(w.p, byte(len(s)))
	w.p = append(w.p, s...)
}

// Raw appends all bytes from b.
func (w *Writer) Raw(b []byte) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, b...)
}

// Obj appends the bytes returned by v.MarshalBinary. If MarshalBinary returns
// an error, it is recorded in the Writer and the buffer is left unchanged.
func (w *Writer) Obj(v encoding.BinaryMarshaler) {
	if w.err != nil {
		return
	}
	b, err := v.MarshalBinary()
	if err != nil {
		w.err = fmt.Errorf("writer: marshal failed at %s: %w", callerLoc(1), err)
		return
	}
	w.p = append(w.p, b...)
}

// Bytes returns the accumulated buffer, or an empty slice if an error occurred.
func (w *Writer) Bytes() []byte {
	if w.err != nil {
		return []byte{}
	}
	return w.p
}

// Err returns the accumulated error, or nil if none occurred.
func (w *Writer) Err() error {
	return w.err
}
